            "selected": true
          }
        ],
        "asset": "resources/base/media/icon_schedule.png"
      },
      "data": {
        "calendar": {
          "items": [
            {
              "entityName": "calendar",
              "entityId": "",
              "title": "取餐时间",
              "dtStart": "读取取餐时间",
              "dtEnd": ""
            }
          ]
        }
      },
      "state": {
        "loading": true
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "schedule_glyph",
      "src": "resources/base/media/icon_schedule.png",
      "use": "calendar pickup glyph",
      "description": "日程图标，用于表达取餐时间来自本地日历。",
      "bindTo": "/groupBuy/asset",
      "static": true
    }
  ]
}

